pm.sendRequest({
    url: pm.environment.get("baseURL") + "/games?limit=3&page=10",
    method: "GET"
}, function (err, response) {
    if (!err) {
        pm.collectionVariables.set("page10Data", JSON.stringify(response.json()));
    }
});

let page9Data = pm.response.json();
let page10Data = JSON.parse(pm.collectionVariables.get("page10Data"));

pm.test("Páginas diferentes devem retornar itens diferentes", function () {
    let page9Ids = page9Data.data.map(item => item.id);
    let page10Ids = page10Data.data.map(item => item.id);

    let hasOverlap = page9Ids.some(id => page10Ids.includes(id));
    pm.expect(hasOverlap).to.be.false;
});

pm.test("Ambas as páginas devem retornar dados", function () {
    pm.expect(page9Data.data).to.be.an('array').that.is.not.empty;
    pm.expect(page10Data.data).to.be.an('array').that.is.not.empty;
});

